(window._lmI18nQueue = window._lmI18nQueue || []).push(["es", "site-help-glossary", {
"site.help.glossary.playNow": "Jugar ahora",
"site.help.glossary.helpCenter": "Centro de ayuda",
"site.help.glossary.strategyGuide": "Guía de estrategia",
"site.help.glossary.unblocked": "🔓 Desbloqueado",
"site.help.glossary.glossary": "Glosario",
"site.help.glossary.ioGamesGlossary": "Glosario de juegos IO",
"site.help.glossary.termsEveryIoGame": "Más de 40 términos que todo jugador de juegos IO debería conocer. De los controles básicos a las técnicas avanzadas: el diccionario completo de Agar.io, Slither.io, Expanding Land y todos los juegos de células.",
"site.help.glossary.jumpToCategory": "Ir a la categoría",
"site.help.glossary.basics": "🎮 Lo básico",
"site.help.glossary.controls": "⌨️ Controles",
"site.help.glossary.mechanics": "⚙️ Mecánicas",
"site.help.glossary.techniques": "🎯 Técnicas",
"site.help.glossary.strategy": "🧠 Estrategia",
"site.help.glossary.community": "👥 Comunidad",
"site.help.glossary.expandingLand": "🌍 Expanding Land",
"site.help.glossary.searchTermsEG": "🔍 Buscar términos... (p. ej. 'split', 'virus', 'W')",
"site.help.glossary.noTermsFoundTry": "No se encontraron términos. Prueba con otra búsqueda.",
"site.help.glossary.cell": "<span class=\"emoji\">⚪</span> Célula",
"site.help.glossary.theCircularBlobYou": "La bola circular que controlas en el juego. Tu célula crece comiendo puntos de comida y otras células más pequeñas. En Agar.io y Expanding Land empiezas como una célula diminuta e intentas convertirte en la más grande del servidor.",
"site.help.glossary.alsoCalledBlobPlayer": "También llamada: blob, jugador, bola",
"site.help.glossary.mass": "<span class=\"emoji\">⚖️</span> Masa",
"site.help.glossary.theSizeWeightOf": "El tamaño/peso de tu célula, mostrado como un número. Más masa = célula más grande. Ganas masa comiendo comida, otros jugadores o virus (si eres lo bastante grande). Pierdes masa por el decaimiento natural con el tiempo: alrededor del 0,8 % cada 4 segundos con las reglas estándar de Agar.io.",
"site.help.glossary.alsoCalledSizeScore": "También llamada: tamaño, puntuación, peso",
"site.help.glossary.foodPellets": "<span class=\"emoji\">🟢</span> Comida / bolitas",
"site.help.glossary.smallColoredDotsScattered": "Pequeños puntos de colores repartidos por el mapa. Al comerlos ganas un poco de masa (normalmente 1 por bolita). Reaparecen sin parar, así que siempre hay algo que comer: muy útil al principio de la partida, cuando eres demasiado pequeño para comerte a otros jugadores.",
"site.help.glossary.leaderboard": "<span class=\"emoji\">🏆</span> Clasificación",
"site.help.glossary.theRankedListOf": "La lista de los mejores jugadores por masa, en la esquina superior derecha. Entrar en la clasificación te convierte en un objetivo: todos los jugadores ambiciosos irán a por ti. En Expanding Land la clasificación se actualiza en tiempo real para los 3840 jugadores.",
"site.help.glossary.spawn": "<span class=\"emoji\">🔄</span> Spawn",
"site.help.glossary.theActOfEntering": "Entrar en el juego con una célula nueva. Al hacer spawn empiezas con un poco de masa en un punto aleatorio del mapa. Después de morir puedes hacer respawn al instante con una célula nueva.",
"site.help.glossary.controlsKeys": "⌨️ Controles y teclas",
"site.help.glossary.splitSpace": "<span class=\"emoji\">✂️</span> Split (Space)",
"site.help.glossary.pressSpaceToSplit": "Pulsa <strong>Space</strong> para hacer split y dividir tu célula en dos mitades. Una mitad sale disparada hacia delante a gran velocidad: úsalo para atrapar a jugadores más pequeños que creen estar fuera de tu alcance. Puedes hacer split hasta 16 veces (16 fragmentos de célula). Las células divididas se vuelven a unir cuando termina un tiempo de espera.",
"site.help.glossary.the2RuleYou": "💡 La regla del 2×: solo puedes comerte una célula si tienes al menos 2× su masa. Al hacer split, cada mitad conserva su impulso: úsalo para sorprender a objetivos lejanos.",
"site.help.glossary.wEjectMass": "<span class=\"emoji\">🟡</span> W (expulsar masa)",
"site.help.glossary.pressWToEject": "Pulsa <strong>W</strong> para expulsar una pequeña bola de masa hacia donde apunta tu cursor. Usos: hacer feed a tus compañeros, disparar virus (7 pulsaciones de W = disparo de virus), poner cebos en trampas o reducir tu tamaño para moverte más rápido. Cada pulsación de W cuesta unos 15-16 de masa, pero la bola expulsada es algo más pequeña por la pérdida de masa.",
"site.help.glossary.alsoCalledFeedEject": "También llamado: feed, eject, disparar masa",
"site.help.glossary.spectate": "<span class=\"emoji\">👁️</span> Espectar",
"site.help.glossary.watchTheGameWithout": "Mira la partida sin jugar. En Expanding Land hay más de 200 plazas de espectador con cámara libre: puedes volar por todo el mapa y observar a cualquier jugador. Ideal para aprender técnicas de jugadores con experiencia.",
"site.help.glossary.gameMechanics": "⚙️ Mecánicas del juego",
"site.help.glossary.virus": "<span class=\"emoji\">🟢</span> Virus",
"site.help.glossary.theSpikyGreenCircles": "Los círculos verdes con pinchos del mapa. Si eres más grande que un virus y lo tocas, <strong>revientas</strong>: tu célula se divide en muchos trozos pequeños. Si eres más pequeño, puedes esconderte detrás o dentro de un virus para protegerte. También puedes disparar virus a los enemigos: pulsa W 7 veces sobre un virus para lanzar uno nuevo en esa dirección.",
"site.help.glossary.virusesAreBothDefensive": "💡 Los virus son a la vez escudos defensivos y armas ofensivas. Los jugadores hábiles usan disparos de virus para reventar a enemigos grandes y robarles la masa.",
"site.help.glossary.mergeRecombine": "<span class=\"emoji\">🔗</span> Fusión / recombinar",
"site.help.glossary.afterSplittingYourCell": "Después de un split, los fragmentos de tu célula acaban fusionándose de nuevo en una sola. El tiempo de fusión depende de tu masa total: las células más grandes tardan más. Durante la espera tus células se superponen pero no se unen. Cuando el tiempo se agota, se juntan de golpe.",
"site.help.glossary.decay": "<span class=\"emoji\">📉</span> Decaimiento",
"site.help.glossary.allCellsLoseMass": "Todas las células pierden masa con el tiempo. Esto se llama decaimiento (decay) e impide que cualquier jugador crezca sin límite. La tasa de decaimiento en Agar.io estándar y en Expanding Land es de aproximadamente <strong>el 0,8 % de tu masa cada 4 segundos</strong>. Las células grandes pierden más en términos absolutos: una célula de 10.000 de masa pierde ~80 por ciclo, mientras que una de 100 pierde menos de 1.",
"site.help.glossary.ghostCells": "<span class=\"emoji\">👻</span> Células fantasma",
"site.help.glossary.inExpandingLandWhen": "En Expanding Land, cuando mueres tus células aparecen un momento como «células fantasma» transparentes que muestran exactamente dónde te comieron. Así entiendes qué pasó y aprendes de tu muerte: ¿fue un split kill? ¿Reventaste en un virus? ¿Un compañero hizo feed?",
"site.help.glossary.mapArena": "<span class=\"emoji\">🗺️</span> Mapa / arena",
"site.help.glossary.thePlayingFieldWhere": "El campo de juego donde están todas las células. En Agar.io el mapa tiene un tamaño fijo. En Expanding Land el mapa <strong>cambia de tamaño dinámicamente</strong> de ¼× a 4× según el número de jugadores activos: más jugadores significa una arena más grande y menos jugadores, un mapa más ajustado que mantiene la acción densa.",
"site.help.glossary.advancedTechniques": "🎯 Técnicas avanzadas",
"site.help.glossary.tricksplit": "<span class=\"emoji\">🎯</span> Tricksplit",
"site.help.glossary.anAdvancedMoveWhere": "Un movimiento avanzado en el que haces split varias veces muy rápido (doble o triple split) para alcanzar un objetivo que parece demasiado lejos. Al hacer split con las células ya divididas, cada trozo sale disparado con impulso y tu alcance efectivo llega mucho más lejos que con un solo split. Requiere un timing preciso y buena colocación del cursor.",
"site.help.glossary.doubleSplitSpaceSpace": "💡 Doble split: Space → Space rápido. Tu segundo split sale del fragmento que ya está en movimiento y cubre 2× la distancia.",
"site.help.glossary.popsplit": "<span class=\"emoji\">💥</span> Popsplit",
"site.help.glossary.aTechniqueWhereYou": "Una técnica en la que te comes un virus a propósito para dividirte en muchos trozos y enseguida haces split otra vez para comerte a un enemigo cercano. La idea es que tus muchas células pequeñas del reventón más el impulso del split te permiten engullir a un enemigo que se creía a salvo. Mucho riesgo, mucha recompensa: necesitas masa suficiente para sobrevivir al reventón.",
"site.help.glossary.baitAndSwitch": "<span class=\"emoji\">🪤</span> Cebo y cambio",
"site.help.glossary.aStrategyWhereYou": "Una estrategia en la que usas un trozo pequeño de tu célula dividida como cebo. El enemigo persigue tu trozo pequeño sin darse cuenta de que tu trozo grande está colocado para comérselo con un split en cuanto se lance. Funciona mejor cuando tienes 2 células de distinto tamaño.",
"site.help.glossary.cannonSelfFeed": "<span class=\"emoji\">🔫</span> Cañón / self-feed",
"site.help.glossary.rapidlyPressingWTo": "Pulsar W muy rápido para pasar masa de una de tus células a otra. Cuando tienes dos células divididas, puedes hacer W desde la más pequeña hacia la más grande para que sea lo bastante grande como para comerse a un objetivo cercano. También se llama «self-feed» porque te haces feed a ti mismo entre tus propias células.",
"site.help.glossary.virusShot": "<span class=\"emoji\">🚀</span> Disparo de virus",
"site.help.glossary.pressingWIntoA": "Pulsar W 7 veces sobre un virus lanza un virus nuevo en esa dirección. Úsalo en ataque para reventar a enemigos grandes o en defensa para crear cobertura. Cada pulsación de W sobre un virus cuesta masa, así que 7 pulsaciones = unos 100-110 de masa en total. El virus lanzado vuela en línea recta hasta que se detiene.",
"site.help.glossary.lineSplit": "<span class=\"emoji\">➡️</span> Line split",
"site.help.glossary.splittingInAStraight": "Hacer split en línea recta hacia tu objetivo para que tu célula dividida recorra la mayor distancia posible. Si colocas el cursor lejos, en línea recta con tu célula y con el objetivo, el trozo sale con la máxima velocidad. Imprescindible para kills a larga distancia.",
"site.help.glossary.strategyConcepts": "🧠 Estrategia y conceptos",
"site.help.glossary.teaming": "<span class=\"emoji\">🤝</span> Teaming",
"site.help.glossary.twoOrMorePlayers": "Dos o más jugadores que cooperan para dominar el servidor. Los compañeros se hacen feed (W), coordinan ataques con virus y se protegen entre sí. El teaming es polémico: hay quien lo considera injusto en los modos free-for-all. Expanding Land tiene un <strong>sistema anti-teaming</strong> que aplica penalizaciones de decaimiento de masa a quienes hacen teaming en exceso.",
"site.help.glossary.antiTeaming": "<span class=\"emoji\">⚖️</span> Anti-teaming",
"site.help.glossary.aSystemThatPenalizes": "Un sistema que penaliza a los jugadores por hacer teaming en exceso. En Expanding Land, el anti-teaming usa un <strong>sistema de decaimiento con multiplicador exponencial</strong> (portado de Delta Server): cada acción (reventón en un virus, split, pulsación de W) aumenta un único valor multiplicador. Tu decaimiento efectivo se calcula como base_decay × pow(1.086, multiplier). El multiplicador baja solo con el tiempo mediante una constante de compensación, así que con un juego normal te recuperas automáticamente, sin temporizadores.",
"site.help.glossary.multiboxing": "<span class=\"emoji\">📱</span> Multiboxing",
"site.help.glossary.playingWithMultipleBrowser": "Jugar con varias pestañas del navegador o varias cuentas a la vez, controlando varias células al mismo tiempo. En Expanding Land el multiboxing está <strong>permitido pero regulado</strong>: cada jugador puede usar hasta <strong>4 cuentas</strong>. Así los jugadores hábiles pueden hacer multibox de forma estratégica y el juego sigue siendo justo.",
"site.help.glossary.bots": "<span class=\"emoji\">🤖</span> Bots",
"site.help.glossary.automatedPlayersControlledBy": "Jugadores automáticos controlados por software en lugar de por personas. En Expanding Land, los bots del servidor y los jugadores humanos son poblaciones distintas. Consulta la <a href=\"/no-bots.html\">guía de bots</a>.",
"site.help.glossary.cornerTrap": "<span class=\"emoji\">🧱</span> Trampa de esquina",
"site.help.glossary.trappingAPlayerIn": "Atrapar a un jugador en una esquina del mapa de la que no puede escapar. El borde del mapa bloquea el movimiento, así que si eres lo bastante grande y te colocas entre el enemigo y la esquina, no tiene adónde ir. Uno de los métodos más fiables para conseguir kills entre los jugadores con experiencia.",
"site.help.glossary.soloFfa": "<span class=\"emoji\">🎮</span> Solo / FFA",
"site.help.glossary.ffaStandsForFree": "<strong>FFA</strong> significa Free-For-All (todos contra todos). Cada jugador compite por su cuenta, sin equipos asignados.",
"site.help.glossary.slowPlay": "<span class=\"emoji\">🐢</span> Juego lento",
"site.help.glossary.aPatientStrategyWhere": "Una estrategia paciente en la que evitas hacer split salvo que tengas un kill asegurado. En lugar de perseguir cada objetivo, creces comiendo comida y esperas a que los enemigos cometan errores. Los jugadores lentos suelen sobrevivir más tiempo y acumular masa de forma constante. Especialmente eficaz en arenas con muchos jugadores como Expanding Land.",
"site.help.glossary.communityMods": "👥 Comunidad y mods",
"site.help.glossary.modExtension": "<span class=\"emoji\">🧩</span> Mod / extensión",
"site.help.glossary.aBrowserExtensionThat": "Una extensión del navegador que mejora el juego con funciones extra: skins personalizados, minimapa, control del zoom, macros y más. Entre los mods populares para Agar.io y Expanding Land están <a href=\"https://www.legendmod.ml/\" style=\"color:#6ee7b7\">Legend Mod</a>, <a href=\"https://deltio.pages.dev/\" style=\"color:#6ee7b7\">Delta</a> y <a href=\"https://agar2.com/\" style=\"color:#6ee7b7\">Agar2</a>.",
"site.help.glossary.skin": "<span class=\"emoji\">🎨</span> Skin",
"site.help.glossary.aCustomImageDisplayed": "Una imagen personalizada que se muestra sobre tu célula en lugar del color por defecto. Los skins pueden ser banderas de países, memes, logotipos o diseños propios. En Agar.io la mayoría de los skins son de pago. En Expanding Land los skins son <strong>gratis</strong> con mods como Legend Mod.",
"site.help.glossary.clan": "<span class=\"emoji\">🏰</span> Clan",
"site.help.glossary.aGroupOfPlayers": "Un grupo de jugadores que juegan juntos y que suelen identificarse con un tag común en el nombre (p. ej., [LC] para <a href=\"https://join.lc\" style=\"color:#6ee7b7\">Legend Clan</a>). Los clanes suelen tener sus propios servidores de Discord, sesiones de entrenamiento y clasificaciones internas.",
"site.help.glossary.privateServer": "<span class=\"emoji\">🖥️</span> Servidor privado",
"site.help.glossary.aGameServerRun": "Un servidor de juego que funciona de forma independiente de los servidores oficiales de Agar.io. Los servidores privados pueden tener reglas propias, límites de jugadores más altos y otras funciones. <a href=\"https://expanding.land/\" style=\"color:#6ee7b7\">Expanding Land</a> es un servidor privado creado desde cero en C, con capacidad para hasta 3840 jugadores por arena.",
"site.help.glossary.expandingLandTerms": "🌍 Términos de Expanding Land",
"site.help.glossary.dynamicMap": "<span class=\"emoji\">🗺️</span> Mapa dinámico",
"site.help.glossary.expandingLandSMap": "El mapa de Expanding Land cambia de tamaño automáticamente según el número de jugadores activos. Más jugadores = mapa más grande. Menos jugadores = mapa más pequeño. El mapa va de ¼× a 4× del tamaño estándar, de modo que la densidad de jugadores se mantiene igual sin importar cuánta gente esté conectada.",
"site.help.glossary.dangerZone": "<span class=\"emoji\">⚠️</span> Zona de peligro",
"site.help.glossary.whenTheExpandingLand": "Cuando el mapa de Expanding Land se está contrayendo (encogiendo), el anillo exterior se convierte en la «zona de peligro». Los jugadores con células en esa zona reciben aumentos del multiplicador anti-team (+0.01 por ciclo de decaimiento). La zona de peligro empuja a los jugadores hacia el centro mientras el mapa se encoge y evita que se queden acampando en los bordes.",
"site.help.glossary.sessionStats": "<span class=\"emoji\">📊</span> Estadísticas de la sesión",
"site.help.glossary.afterDyingInExpanding": "Al morir en Expanding Land ves las estadísticas de tu sesión: tiempo vivo, masa máxima alcanzada, comida ingerida y jugadores que te comiste. Estas estadísticas te ayudan a seguir tu progreso con el tiempo y a comparar tu rendimiento entre sesiones.",
"site.help.glossary.coordinateScrambling": "<span class=\"emoji\">🔒</span> Codificación de coordenadas",
"site.help.glossary.anAntiCheatFeature": "Una función anti-cheat de Expanding Land en la que el servidor envía un desplazamiento de coordenadas distinto a cada jugador. Así es imposible que las herramientas de trampas lean las posiciones exactas de otros jugadores en los paquetes de red: la vista de cada jugador se codifica de forma diferente.",
"site.help.glossary.wssTls": "<span class=\"emoji\">🔐</span> WSS / TLS",
"site.help.glossary.encryptedWebsocketConnectionsUsed": "Conexiones WebSocket cifradas que usa Expanding Land. Todos los datos entre tu navegador y el servidor del juego se cifran con TLS (la misma tecnología que protege la banca online). Esto impide el espionaje de paquetes y los ataques man-in-the-middle.",
"site.help.glossary.playExpandingLandFree": "🎮 Juega a Expanding Land gratis",
"site.help.glossary.bestIoGames2026": "Mejores juegos IO 2026",
"site.help.glossary.elVsAgarIo": "EL vs Agar.io",
"site.help.glossary.playersAndBots": "Jugadores y bots"
}]);
if (window.LMi18n && window.LMi18n._drain) window.LMi18n._drain();
